#!/bin/bash
set -eo pipefail
BUILDDIR=$1
OUTPUTDIR=$3
PROJECTDIR=$4
mkdir -p "$OUTPUTDIR"

# ROM resources are imported by the game, not generated by the desktop build.
python3 "$PROJECTDIR/tools/scripts/install_pc_config.py" "$OUTPUTDIR" "$PROJECTDIR/tools/config"
if [ ! -e "$OUTPUTDIR/firmware.bin" ]; then
  dd if=/dev/zero of="$OUTPUTDIR/firmware.bin" bs=1584 count=1 2>/dev/null
  printf '\300\000' | dd of="$OUTPUTDIR/firmware.bin" bs=1 seek=32 conv=notrunc 2>/dev/null
fi
MainStaging=$(mktemp "$OUTPUTDIR/.main.XXXXXX")
trap 'rm -f "$MainStaging"' EXIT
cp -p "$BUILDDIR/main" "$MainStaging"
mv -f "$MainStaging" "$OUTPUTDIR/main"

mkdir -p "$OUTPUTDIR/mods"
if compgen -G "$BUILDDIR/mods/*.so" > /dev/null; then
  for ModFile in "$BUILDDIR"/mods/*.so; do
    ModName=$(basename "$ModFile" .so)
    mkdir -p "$OUTPUTDIR/mods/$ModName"
    cp "$ModFile" "$OUTPUTDIR/mods/$ModName/$ModName.so"
    rm -f "$OUTPUTDIR/mods/$ModName.so"
  done
fi

for LuaFile in "$BUILDDIR"/mods/*.lua; do
  [ -f "$LuaFile" ] || continue
  ModName=$(basename "$LuaFile" .lua)
  mkdir -p "$OUTPUTDIR/mods/$ModName"
  cp "$LuaFile" "$OUTPUTDIR/mods/$ModName/$ModName.lua"
done
for DefaultConfig in "$PROJECTDIR"/mods/*/*.ini; do
  [ -f "$DefaultConfig" ] || continue
  ModName=$(basename "$(dirname "$DefaultConfig")")
  mkdir -p "$OUTPUTDIR/mods/$ModName"
  if [ ! -e "$OUTPUTDIR/mods/$ModName/$(basename "$DefaultConfig")" ]; then
    cp "$DefaultConfig" "$OUTPUTDIR/mods/$ModName/"
  fi
done

mkdir -p "$OUTPUTDIR/mods/fast_ball_battle"
for ResourceFile in \
  fast_ball_battle_frame.ncgr \
  fast_ball_battle_frame.nclr \
  fast_ball_battle_cell.ncer \
  fast_ball_battle_anim.nanr; do
  cp "$BUILDDIR/mods/$ResourceFile" "$OUTPUTDIR/mods/fast_ball_battle/$ResourceFile"
  rm -f "$OUTPUTDIR/mods/$ResourceFile"
done

mkdir -p "$OUTPUTDIR/mods/level_cap"
if [ ! -e "$OUTPUTDIR/mods/level_cap/level_caps.json" ]; then
  if [ -e "$OUTPUTDIR/mods/level_caps.json" ]; then
    mv "$OUTPUTDIR/mods/level_caps.json" "$OUTPUTDIR/mods/level_cap/level_caps.json"
  else
    cp "$PROJECTDIR/mods/level_cap/level_caps.json" "$OUTPUTDIR/mods/level_cap/level_caps.json"
  fi
fi

if [[ "$4" == "-nx" ]]; then
  /opt/devkitpro/tools/bin/elf2nro $OUTPUTDIR/main $OUTPUTDIR/pokeplatinum.nro
else
  if [[ "$(uname -s)" =~ ^MSYS_NT.* ]]; then
    cp -u /ucrt64/bin/SDL2.dll $OUTPUTDIR/SDL2.dll
    cp -u /ucrt64/bin/libwinpthread-1.dll $OUTPUTDIR/libwinpthread-1.dll
    cp -u /ucrt64/bin/libenet-7.dll $OUTPUTDIR/libenet-7.dll
    cp -u /ucrt64/bin/libgcc_s_seh-1.dll $OUTPUTDIR/libgcc_s_seh-1.dll
    cp -u /ucrt64/bin/libstdc++-6.dll $OUTPUTDIR/libstdc++-6.dll
  else
    AppDir="$BUILDDIR/.build-temp/pokeplatinum.AppDir"
    LinuxDeploy="$PROJECTDIR/tools/linuxdeploy/linuxdeploy-x86_64.AppImage"
    mkdir -p "$AppDir/usr/bin" "$AppDir/usr/lib"
    cp "$BUILDDIR/main" "$AppDir/usr/bin/app"
    if [ ! -f "$LinuxDeploy" ]; then
      echo "Downloading linuxdeploy..."
      wget https://github.com/linuxdeploy/linuxdeploy/releases/download/continuous/linuxdeploy-x86_64.AppImage -O "$LinuxDeploy"
      chmod +x "$LinuxDeploy"
    fi
    (cd "$BUILDDIR" && NO_STRIP=1 "$LinuxDeploy" --appdir "$AppDir" --executable="$OUTPUTDIR/main" --desktop-file="$PROJECTDIR/tools/linuxdeploy/App.desktop" --icon-file="$PROJECTDIR/tools/linuxdeploy/app.png" --output appimage)
    mv "$BUILDDIR/pokeplatinum-x86_64.AppImage" "$OUTPUTDIR/pokeplatinum.AppImage"
  fi
fi
